let themePoll: Timer | null = null
let ageTick: Timer | null = null
let themeMtime: number | null = null
let generation = 0
let lastPress = { key: '', at: 0 }
let noNerd = false
let glyphSetting = 'auto'
let openWithSetting = ''
let previewed: { path: string; text: string; note: string } | null = null
let previewRows = 20
